import { getRequest as baseGetRequest, patchRequest as basePatchRequest, postRequest as basePostRequest, } from "../utils.js";
export class BaseReader {
    deps;
    constructor(deps) {
        this.deps = deps;
    }
    mergeHeaders(options) {
        const extra = this.deps.config.additionalHeaders;
        if (!extra)
            return options;
        return {
            ...options,
            headers: {
                ...extra,
                ...options?.headers,
            },
        };
    }
    async view(fn, args, typeArguments = []) {
        return this.deps.aptos.view({
            payload: {
                function: fn,
                typeArguments,
                functionArguments: args,
            },
        });
    }
    async getRequest(args) {
        return baseGetRequest({
            ...args,
            options: this.mergeHeaders(args.options),
            apiKey: this.deps.apiKey,
        });
    }
    async postRequest(args) {
        return basePostRequest({
            ...args,
            options: this.mergeHeaders(args.options),
            apiKey: this.deps.apiKey,
        });
    }
    async patchRequest(args) {
        return basePatchRequest({
            ...args,
            options: this.mergeHeaders(args.options),
            apiKey: this.deps.apiKey,
        });
    }
}
